llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Entecavir, a carbocyclic guanine nucleoside with the closest structural similarity to the query, has an absolute oral bioavailability of 100% in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Fludarabine, a purine nucleoside analogue, shows approximately 55% oral bioavailability in patients, supporting moderate-to-good oral absorption for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Clofarabine, a related halogenated purine nucleoside, is rapidly absorbed with about 57.5% oral bioavailability, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Cladribine tablets have an estimated oral bioavailability of 45.6% in patients, supporting F ≥ 20% for a polar purine nucleoside analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Didanosine under fed conditions had a median F of 0.19, below the 20% threshold, but this is condition-specific and from a less similar hypoxanthine dideoxynucleoside, providing only weak contrary evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue entecavir has 100% absolute oral bioavailability, and multiple purine nucleoside analogues show 40–60% oral bioavailability, strongly supporting F ≥ 20%. The only sub-20% values are condition-specific didanosine data with low structural transferability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule; prediction relies on analogue extrapolation.",
    "Fed-state and pediatric didanosine data may not reflect typical adult oral absorption of the query.",
    "Potential transporter/efflux liabilities of the cyclobutane bis-hydroxymethyl guanine scaffold are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

